package com.tapeverify.copilot.util;
import static org.junit.jupiter.api.Assertions.*; import com.tapeverify.copilot.entity.*; import java.math.*; import java.time.*; import org.junit.jupiter.api.Test;
class HashUtilTest { @Test void canonicalHashIgnoresDecimalScaleAndBorrowerWhitespace(){Loan a=loan(new BigDecimal("100.0")," Ada   Lovelace ");Loan b=loan(new BigDecimal("100.00"),"Ada Lovelace");assertEquals(HashUtil.hash(a),HashUtil.hash(b));b.setPrincipalAmount(new BigDecimal("101"));assertNotEquals(HashUtil.hash(a),HashUtil.hash(b));} private Loan loan(BigDecimal amount,String name){return Loan.builder().batchId("batch").borrowerName(name).principalAmount(amount).interestRate(new BigDecimal("5.0")).originationDate(LocalDate.of(2024,1,1)).maturityDate(LocalDate.of(2025,1,1)).status(LoanStatus.VALID).sha256Hash("").createdAt(LocalDateTime.now()).build();}}
